package com.hau.notification.infrastructure.websocket;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Configuration;import org.springframework.messaging.simp.config.MessageBrokerRegistry;import org.springframework.web.socket.config.annotation.*;
@Configuration @EnableWebSocketMessageBroker public class WebSocketConfiguration implements WebSocketMessageBrokerConfigurer{private final String[] origins;public WebSocketConfiguration(@Value("${CORS_ALLOWED_ORIGINS:http://localhost:5173}")String origins){this.origins=origins.split(",");}public void registerStompEndpoints(StompEndpointRegistry r){r.addEndpoint("/ws").setAllowedOriginPatterns(origins);}public void configureMessageBroker(MessageBrokerRegistry r){r.enableSimpleBroker("/queue");r.setUserDestinationPrefix("/user");}}
